let attachmentDraft=[],attachmentBusy=false;
function attachmentDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('youxu-files',1);r.onupgradeneeded=()=>r.result.createObjectStore('pdfs');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('文件库被其他页面占用，请关闭旧标签后重试'))})}
async function attachmentStore(mode,action){const db=await attachmentDB();try{return await new Promise((resolve,reject)=>{const tx=db.transaction('pdfs',mode);let request;try{request=action(tx.objectStore('pdfs'))}catch(e){reject(e);return}tx.oncomplete=()=>resolve(request?.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('文件保存被中断'))})}finally{db.close()}}
function attachmentEditor(note){if(window.gradlifeCloud){attachmentDraft=(note.attachments||[]).map(x=>({...x}));return '<p class="muted">PDF 云存储尚未启用，请先添加相关链接。本机版的 PDF 文件保留在原浏览器。</p>'}attachmentDraft=(note.attachments||[]).map(x=>({...x}));return `<details class="note-links-editor" ${attachmentDraft.length?'open':''}><summary>PDF 附件（可选）</summary><p class="muted">每个 PDF 最多 20MB。文件仅保存在当前浏览器；清除网站数据会删除文件。JSON 导出不包含 PDF，请另行下载备份。</p><input id="attachment-input" type="file" accept="application/pdf,.pdf" multiple aria-label="添加 PDF 附件"><div id="attachment-draft"></div><p id="attachment-status" role="status"></p></details>`}
function attachmentButtons(a,draft=false){return `<div class="attachment-row"><span>${esc(a.name)} <small class="muted">${(a.size/1048576).toFixed(1)} MB</small></span><div><button type="button" data-preview-attachment="${a.id}" ${a.file?'disabled':''}>预览</button><button type="button" data-download-attachment="${a.id}" ${a.file?'disabled':''}>下载</button>${draft?`<button type="button" data-remove-attachment="${a.id}">移除</button>`:''}</div></div>`}
function renderAttachmentDraft(){if($('#attachment-draft'))$('#attachment-draft').innerHTML=attachmentDraft.map(a=>attachmentButtons(a,true)).join('')}
function attachmentView(note){return (note.attachments||[]).map(a=>attachmentButtons(a)).join('')}
async function saveNoteWithAttachments(values){if(attachmentBusy){toast('请等待文件检查完成');return}const form=$('#form'),submit=form.querySelector('[type=submit]');submit.disabled=true;attachmentBusy=true;const added=attachmentDraft.filter(a=>a.file),old=editing?state.notes.find(n=>n.id===editing):null;try{if(added.length)await attachmentStore('readwrite',store=>{added.forEach(a=>store.put(a.file,a.id))});const prior=state.notes;const record={...(old||{}),...values,id:editing||id(),minutes:Number(values.minutes),date:old?.date||today,attachments:attachmentDraft.map(({file,...meta})=>meta)};state.notes=old?state.notes.map(n=>n.id===editing?record:n):[record,...state.notes];if(!(await save())){state.notes=prior;throw Error('记录保存失败，附件未关联；请重试或释放浏览器空间')}$('#dialog').close();render();toast(window.gradlifeCloud?'记录已保存到云端':'记录与 PDF 附件已保存到本机');const removed=(old?.attachments||[]).filter(a=>!record.attachments.some(b=>b.id===a.id));if(removed.length)await attachmentStore('readwrite',store=>removed.forEach(a=>store.delete(a.id))).catch(()=>{})}catch(e){if(added.length)await attachmentStore('readwrite',store=>added.forEach(a=>store.delete(a.id))).catch(()=>{});toast(e.message||'文件保存失败，请检查浏览器存储空间')}finally{attachmentBusy=false;submit.disabled=false}}
document.addEventListener('change',async e=>{if(e.target.id!=='attachment-input')return;const input=e.target;attachmentBusy=true;input.disabled=true;try{const pending=[];for(const file of input.files){if(!file.name.toLowerCase().endsWith('.pdf')||file.size>20*1048576)throw Error('请选择每个不超过 20MB 的 PDF');const header=new TextDecoder().decode(await file.slice(0,1024).arrayBuffer());if(!header.includes('%PDF-'))throw Error(file.name+' 不是有效的 PDF 文件');pending.push({id:crypto.randomUUID(),name:file.name,size:file.size,file})}attachmentDraft.push(...pending);renderAttachmentDraft();$('#attachment-status').textContent='已添加，点击保存后写入文件库。'}catch(e){$('#attachment-status').textContent=e.message}finally{input.value='';input.disabled=false;attachmentBusy=false}});
document.addEventListener('click',async e=>{const button=e.target.closest('button');if(!button)return;const d=button.dataset;if(d.removeAttachment){attachmentDraft=attachmentDraft.filter(a=>a.id!==d.removeAttachment);renderAttachmentDraft();return}const key=d.previewAttachment||d.downloadAttachment;if(!key)return;if(window.gradlifeCloud){toast('此附件尚未迁移到云端，请在原本机工作台打开');return}button.disabled=true;try{const blob=await attachmentStore('readonly',s=>s.get(key));if(!blob)throw Error('此浏览器中找不到附件，文件可能已被清理');const file=new Blob([blob],{type:'application/pdf'}),url=URL.createObjectURL(file),meta=attachmentDraft.find(a=>a.id===key)||state.notes.flatMap(n=>n.attachments||[]).find(a=>a.id===key);if(d.downloadAttachment){const a=document.createElement('a');a.href=url;a.download=meta?.name||'附件.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}else{let dialog=$('#attachment-preview');if(!dialog){dialog=document.createElement('dialog');dialog.id='attachment-preview';document.body.append(dialog)}dialog.innerHTML=`<div class="dialog-head"><h2>${esc(meta?.name||'PDF 预览')}</h2><button type="button" aria-label="关闭预览">×</button></div><p class="muted">若浏览器不支持内嵌预览，请关闭后点击下载。</p><iframe title="PDF 附件预览"></iframe>`;dialog.querySelector('iframe').src=url;dialog.querySelector('button').onclick=()=>dialog.close();dialog.onclose=()=>{dialog.querySelector('iframe').src='about:blank';URL.revokeObjectURL(url)};dialog.showModal()}}catch(e){toast(e.message||'读取附件失败')}finally{button.disabled=false}});
document.addEventListener('click',e=>{if(attachmentBusy&&e.target.closest('#dialog button')){e.preventDefault();e.stopImmediatePropagation()}},true);
document.addEventListener('cancel',e=>{if(attachmentBusy&&e.target.id==='dialog')e.preventDefault()},true);
